static void InitPlayer(int n)
{
    static const char *defaults[] = {
        "Player 1","Player 2","Player 3","Player 4","Player 5","Player 6"
    };
    PlayerState FAR *p = &gPlayers[n];
    memset(p, 0, sizeof(*p));
