        case 'o':
        case 'O': g->sound_on = !g->sound_on; break;
        case 'p':
        case 'P':
            if (g->mode == BO_MODE_GAME) { /* 6106 */
                g->paused_countdown = g->countdown;
                g->state = BO_S_PAUSED;
                return g->state;
