    if (g->mode == BO_MODE_PRACTICE) {
        if (!g->dropped || g->countdown != 0) return g->state;
    } else {
        if (g->countdown != 0) return g->state;
        g->countdown = g->delay;
        if (!g->dropped) {
            int16_t v[3];
            g->h--;
            for (int i = 0; i < bo_ncubes(g); i++) {
                transform(&g->pose, cube(g, i), v);
                if (v[2] < g->h) return g->state; /* still entering the pit */
            }
        }
    }
    if (move_piece(g, 0, 0, -1) == 0) {
        g->dropped = 0;
        return g->state;
    }
    g->resume_at = R_LAND;
    if (anims_busy(g)) {
        g->state = BO_S_LAND_WAIT;
        return g->state;
    }
    goto land;

wait_frame: /* wait_animations (5dd6) */
    g->frame++;
    anim_move_step(g);
    anim_rot_step(g);
    if (anims_busy(g)) return g->state;
    g->state = BO_S_PLAY;
    if (g->resume_at == R_AFTER_DROP) goto after_drop;
    goto land;

land:
    land_lock(g);
    if (g->sound_ticks) {
        g->resume_at = R_AFTER_LAND_SOUND;
        g->state = BO_S_SOUND;
        return g->state;
    }
after_land_sound:
