        } else {
            land_lock(g);
            if (g->sound_ticks) {
                g->resume_at = R_AFTER_LAND_SOUND;
                g->state = BO_S_SOUND;
                return g->state;
            }
            add_score(g);
        demo_spawn:
            g->resume_at = R_DEMO_ACT;
            g->state = BO_S_DEMO;
