    if (g->mode == BO_MODE_DEMO) {
        if (pop_key(g) != -1 || g->ticks >= 0x5b) g->state = BO_S_DONE;
        return g->state;
    }
    while ((k = pop_key(g)) != -1)
        if (k == BO_K_ENTER || k == BO_K_ESC) {
            g->state = BO_S_DONE;
            break;
        }
    return g->state;
}

